#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    // Each thread computes 2x2 elements
    const int TILE_K = 8;  // Tiling in K dimension
    const int THREAD_TILE_M = 2; // Each thread computes 2 elements in M dimension
    const int THREAD_TILE_N = 2; // Each thread computes 2 elements in N dimension

    __shared__ float As[TILE_SIZE][TILE_SIZE + 1];  // +1 to avoid bank conflicts
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Starting row and column for this thread block
    int row_start = by * TILE_SIZE;
    int col_start = bx * TILE_SIZE;

    // Register accumulators for 2x2 output elements
    float c[THREAD_TILE_M][THREAD_TILE_N] = {{0}};

    // Loop over tiles in K dimension
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tiles into shared memory with coalesced access
        int A_col = t * TILE_SIZE + tx;
        int B_row = t * TILE_SIZE + ty;

        // Load A tile (coalesced access)
        if (row_start + ty < N && A_col < N) {
            As[ty][tx] = A[(row_start + ty) * N + A_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load B tile (coalesced access)
        if (B_row < N && col_start + tx < N) {
            Bs[ty][tx] = B[B_row * N + (col_start + tx)];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial products
        for (int k = 0; k < TILE_SIZE; k += TILE_K) {
            // Prefetch next tile while computing current
            float a_prefetch[THREAD_TILE_M];
            float b_prefetch[THREAD_TILE_N];

            for (int i = 0; i < THREAD_TILE_M; i++) {
                a_prefetch[i] = As[ty * THREAD_TILE_M + i][k];
            }
            for (int j = 0; j < THREAD_TILE_N; j++) {
                b_prefetch[j] = Bs[k][tx * THREAD_TILE_N + j];
            }

            // Unroll inner loop
            for (int kk = 0; kk < TILE_K; kk++) {
                float a_val[THREAD_TILE_M];
                float b_val[THREAD_TILE_N];

                for (int i = 0; i < THREAD_TILE_M; i++) {
                    a_val[i] = a_prefetch[i];
                    if (kk < TILE_K - 1) {
                        a_prefetch[i] = As[ty * THREAD_TILE_M + i][k + kk + 1];
                    }
                }
                for (int j = 0; j < THREAD_TILE_N; j++) {
                    b_val[j] = b_prefetch[j];
                    if (kk < TILE_K - 1) {
                        b_prefetch[j] = Bs[k + kk + 1][tx * THREAD_TILE_N + j];
                    }
                }

                // Accumulate products
                for (int i = 0; i < THREAD_TILE_M; i++) {
                    for (int j = 0; j < THREAD_TILE_N; j++) {
                        c[i][j] += a_val[i] * b_val[j];
                    }
                }
            }
        }

        __syncthreads();
    }

    // Store results to global memory
    for (int i = 0; i < THREAD_TILE_M; i++) {
        int row = row_start + ty * THREAD_TILE_M + i;
        for (int j = 0; j < THREAD_TILE_N; j++) {
            int col = col_start + tx * THREAD_TILE_N + j;
            if (row < N && col < N) {
                C[row * N + col] = c[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions mismatch");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block(TILE_SIZE/2, TILE_SIZE/2);  // Each thread handles 2x2 elements
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

